labelExpressionInfo.expression:
var total = DefaultValue($feature.Wheat_prod_2022, 0);
var durum = DefaultValue($feature.Spring_wheat_prod_2022, 0);
var winter = DefaultValue($feature.Winter_wheat_prod_2022, 0);
var spring = DefaultValue($feature.Spring_wheat_prod_nodurum_2022, 0);

return `Total: ${Text(total, "#,###")}
Winter: ${Text(winter, "#,###")}
Spring: ${Text(spring, "#,###")}
Durum: ${Text(durum, "#,###")}
`

expressionInfo.expression:
var diff = $feature.Wheat_prod_2022 - $feature.Wheat_prod_1997;
var color = "black";
var prefix = "";
if (diff > 0){
	color = "#00998c";
	prefix = "increased by";
} else {
	color = "#b34a00";
	prefix = "decreased by";
}

var output = `From 1997 to 2020, total wheat production in ${$feature.NAMELSAD} ${prefix} <b><span style='color:${color}'>${Text(Abs(diff), "#,###")}</span></b> bushels.`;

return { 
	type: 'text', 
	text: output
}

Expects($feature, "Wheat_prod_*", "Winter_wheat_prod_*", "Spring_wheat_prod_*", "Spring_wheat_prod_nodurum_*");

var totalWheatFields = [
  "Wheat_prod_1997",
  "Wheat_prod_2002",
  "Wheat_prod_2007",
  "Wheat_prod_2012",
  "Wheat_prod_2017",
  "Wheat_prod_2022"
];

function featureHasValue(fieldName){
  return HasValue($feature, fieldName);
}

var hasTotalWheatData = Any(totalWheatFields, featureHasValue);

var mediaInfos = [];

if(hasTotalWheatData){
  Push(mediaInfos, {
    altText: "",
    caption: "Values reported in bushels",
    title: "Total wheat production 1997-2022",
    type: "linechart",
    value:
      {
        colors: [[40, 136, 184, 255]],
        fields: totalWheatFields
      }
  });
} else {
  return {
    type: "text",
    text: "This county did not produce any wheat from 1997 - 2022."
  }
}

var media = {
  type: "media",
  title: "Wheat production 1997-2022",
  description:
    "Explore the following charts to explore production of various kinds of wheat for the last 25 years.",
    mediaInfos
};

return media;

